{
  "status": "updated",
  "chapter_updates": [
    {
      "chapter_id": "CH1",
      "updated_plan": {
        "thesis": "可见光波段消色差超构透镜的性能受限于两类物理边界：由色散工程决定的带宽软约束与由单界面几何决定的视场硬约束。在色散方面，基于局部相互作用假设（P0002），有限孔径效应导致群延迟需求随入射角呈现非单调变化，使得带宽随视场的压缩存在饱和平台期，而非简单的线性递减；该结论严格依赖于标量衍射近似，矢量效应或非局部设计可能修正此界限。在几何方面，单层结构固有的彗差与像散将高数值孔径下的低像差视场严格限制在微米量级（P0001）。这两重界限共同确立了当前单层超构透镜的理论性能天花板。",
        "reader_objective": "读者应能理解为何‘视场越大带宽越低’的直觉在宽视场极限下失效（即带宽饱和现象），并明确区分色散工程带来的带宽限制（基于局部相互作用的理论上限）与几何像差带来的视场限制（单层结构的硬性物理约束），从而建立对单层超构透镜物理极限的准确认知，同时知晓现有理论模型的适用边界（如标量近似、局部假设）。",
        "units": [
          {
            "unit_id": "U1",
            "substantive_point": "确立延迟 - 带宽积作为色散工程消色差设计的核心物理矛盾，阐明最大可用光谱带宽直接受限于系统所需的群延迟动态范围，并明确其基于局部相互作用假设的适用范围。",
            "ordered_development": "从理想相位剖面的频率依赖性出发，推导群延迟需求的分布，进而引入一维延迟线的延迟 - 带宽积极限，建立带宽上限公式，并明确指出该界限仅适用于局部超表面。",
            "paragraph_briefs": [
              {
                "point": "定义色散工程消色差金属透镜的理想相位剖面及其频率依赖性。",
                "development": "阐述为了实现宽带无像差聚焦，金属透镜必须在中心频率提供特定的相位分布，同时提供恒定的群延迟以补偿不同入射角和径向位置的光程差。指出相位与群延迟成正比关系。",
                "source_handles": [
                  "P0002"
                ]
              },
              {
                "point": "引入延迟 - 带宽积极限，建立带宽上限公式，并界定其适用条件。",
                "development": "基于局部相互作用假设，将元原子建模为一维延迟线。引用 Miller 的一般性界限（ΔT·Δω ≤ κ），说明任何物理结构所能提供的最大群延迟范围（ΔT）与其工作带宽（Δω）成反比。得出最大可用带宽 Δω ≤ κ / ΔT_max 的核心结论。强调该界限严格依赖于局部相互作用假设，对于强耦合或非局部超表面，常数κ可能发生变化，本章仅讨论局部极限作为基准。",
                "source_handles": [
                  "P0002"
                ]
              }
            ],
            "conditions_and_limits": "该界限严格依赖于局部相互作用假设和一维延迟线模型。对于强耦合、非局部超表面或多层结构，常数κ可能发生变化或模型失效。此外，推导基于标量衍射近似，未包含矢量效应。本章仅讨论局部极限作为基准，非局部效应的修正留作未来展望。",
            "transition": "明确了带宽受限于群延迟范围后，需进一步分析在宽视场条件下，这个决定带宽上限的最大群延迟范围是如何随视场角变化的，以及有限孔径如何导致非单调性。"
          },
          {
            "unit_id": "U2",
            "substantive_point": "揭示有限孔径金属透镜上群延迟需求的非单调性，论证带宽随视场增加而减小并最终趋于饱和的物理机制，同时指出该结论基于标量近似且缺乏解析临界值公式。",
            "ordered_development": "对比无限大透镜与有限孔径透镜的群延迟分布差异，解释掠射角附近的相位需求减小现象，进而推导最大群延迟范围出现在中间临界角度而非最大视场角处，最终导致带宽饱和。补充说明该结论基于标量近似，且文中未提供临界角的解析解。",
            "paragraph_briefs": [
              {
                "point": "分析有限孔径效应对群延迟空间分布的影响。",
                "development": "指出对于无限大理想透镜，所需总相位范围恒定；但对于有限半径 R 的实际透镜，所需相位范围并不随入射角单调增加。在掠射角附近，由于几何投影效应和光程差变化率降低，所需的总相位调制范围反而减小。",
                "source_handles": [
                  "P0002"
                ]
              },
              {
                "point": "论证最大群延迟范围的确定及其对带宽的影响。",
                "development": "说明决定带宽上限的是整个工作视场内最宽的群延迟范围（ΔT_max）。该最大值出现在某个特定角度α*，而非最大视场角处。当设计视场超过α*后，继续扩大视场不会增加ΔT_max，因此可用带宽不再随 FOV 扩大而进一步压缩。",
                "source_handles": [
                  "P0002"
                ]
              },
              {
                "point": "描述带宽饱和现象在不同焦点映射下的普遍性及理论局限。",
                "development": "结合两种焦点位置定义（r0=Ftan(α) 无畸变映射与 r0=Fα 线性映射），指出尽管具体数值不同，但两种情形下均观察到带宽随 FOV 增加先减小后饱和的趋势。强调这是有限孔径几何结构带来的普遍物理约束，但需注意该结论基于标量衍射近似与几何光学假设，且 P0002 未提供α*的解析表达式，本章仅定性描述这一饱和趋势。",
                "source_handles": [
                  "P0002"
                ]
              }
            ],
            "conditions_and_limits": "此结论基于标量衍射近似与几何光学假设。文中未提供α*的解析表达式，本章仅定性描述这一饱和趋势，避免给出错误的通用临界值公式。若考虑矢量效应或非局部设计，该界限可能发生变化。",
            "transition": "虽然色散工程限制了带宽，但即使完美解决色散问题，单层超构透镜仍面临另一重不可逾越的限制——单界面几何像差对视场的硬性约束。"
          },
          {
            "unit_id": "U3",
            "substantive_point": "阐明单界面几何像差对视场的硬约束，确立高数值孔径下单层超构透镜的低像差视场下限，并指出该限制仅针对单层局部相位元件。",
            "ordered_development": "从几何光学角度解释单界面无法校正高阶像差的原理，引用具体量化数据展示高 NA 下极小的低像差视场，从而界定单层结构的适用边界。",
            "paragraph_briefs": [
              {
                "point": "解释单界面几何像差的产生机制。",
                "development": "指出传统复合物镜通过多元件间距校正彗差、场曲和像散，而单层超构透镜缺乏这种空间自由度。斜入射时，瞳孔坐标处的理想相位分布与正入射不同，其差异在小角度展开后对应于标准几何像差项，且随孔径或视场角迅速增大。",
                "source_handles": [
                  "P0001"
                ]
              },
              {
                "point": "提供高 NA 下单层透镜视场受限的具体量化描述。",
                "development": "引用具体案例：对于 NA=0.5、焦距 f=1mm 的单层透镜，在可见光波段，若要求路径延迟误差不超过一个波长（即保持低像差），其有效视场被限制在小于 5 µm 的范围内。这确立了 FOV 的物理下限。",
                "source_handles": [
                  "P0001"
                ]
              },
              {
                "point": "总结单层结构的适用场景与局限。",
                "development": "基于上述量化限制，指出单层高 NA 超构透镜仅适用于点对点互连等小视场应用，而不适合需要大视场的高性能成像系统。这与 CH1 中带宽饱和的结论共同构成了理论性能天花板。强调此限制针对单层局部相位元件，多片式系统或非局部设计可突破此限。",
                "source_handles": [
                  "P0001"
                ]
              }
            ],
            "conditions_and_limits": "此限制针对单层局部相位元件。多片式系统或非局部设计可突破此限，但这已超出单层色散工程的讨论范畴。",
            "transition": "本章建立了理论上的性能边界：带宽受限于延迟 - 带宽积导致的饱和效应（基于局部假设与标量近似），视场受限于单界面几何像差。然而，理论界限的存在并不意味着所有设计都能轻易逼近它。下一章将深入微观层面，探讨在实际纳米结构设计中，为了尝试逼近这些物理界限，元原子本身会遭遇何种效率损耗。"
          }
        ]
      }
    }
  ],
  "unit_id_remap": {}
}

